unsafe fn putd(o:*mut u8,p:usize,x:f64){for(k,b)in x.to_le_bytes().iter().enumerate(){*o.add(p+k)=*b}}
#[no_mangle]
pub unsafe extern "C" fn fuzzy_set_operations(v:*const i64,n:usize,o:*mut u8,cap:usize)->i64{if v.is_null()||n<8{return -1}let a=std::slice::from_raw_parts(v,n);let op=a[0];let m=a[1];if !(0..=8).contains(&op)||!(1..=8).contains(&m)||n!=5+3*m as usize{return -1}if a[5..].iter().any(|x|!(0..=1000).contains(x)){return -1}let(l,p,r)=(a[2],a[3],a[4]);if op==0{if l<0||p<l||r<p||r>1000||(0..m as usize).any(|i|a[5+m as usize+i]!=0||a[5+2*m as usize+i]!=0){return -1}}else if l!=0||p!=0||r!=0||(0..m as usize).any(|i|a[5+i]!=0){return -1}if o.is_null()||cap<m as usize*8{return -2}for i in 0..m as usize{let z=if op==0{let x=a[5+i] as f64/1000.;let l=l as f64/1000.;let p=p as f64/1000.;let r=r as f64/1000.;let u=if p>l{(x-l)/(p-l)}else if x<p{0.}else{1.};let w=if r>p{(r-x)/(r-p)}else if x>r{0.}else{1.};u.min(w).clamp(0.,1.)}else{let x=a[5+m as usize+i] as f64/1000.;let y=a[5+2*m as usize+i] as f64/1000.;match op{1=>x.max(y),2=>x.min(y),3=>1.-x,4=>x.min(1.-y),5=>x+y-x*y,6=>x*y,7=>(x+y).min(1.),_ =>(x+y-1.).max(0.)}};putd(o,i*8,z)}m*8}
